import {escapeHTML as e} from '../../shared/primitives.js';
import {icon,pageHeading,badge,empty} from '../../shared/ui.js';
const locationName=(c,id)=>c.locations.find(l=>l.id===id)?.name||'Local desconhecido';
const button=(action,label,primary=false)=>`<button class="${primary?'primary':''}" data-action="${action}">${icon('plus')}${label}</button>`;
export function tournamentView(c) {
 const name=id=>c.characters.find(ch=>ch.id===id)?.name||'A definir';
 return `${pageHeading('O CAMPO DO LEÃO','Campeonato de Batalhas','Planejamento separado do cânone: registre confrontos quando forem definidos.',button('new-match','Novo confronto',true))}<div class="tournament-layout"><section class="panel"><div class="section-line"><span class="eyebrow">REGULAMENTO E PLANEJAMENTO</span><button class="text-button" data-action="edit-rules">Editar ↗</button></div><div class="prose">${e(c.tournament.rules||'Defina o regulamento deste campeonato.')}</div><p class="muted">Resultados são registrados manualmente. Os ranks não geram resultados automáticos.</p></section><section><div class="section-line"><h2>Confrontos</h2><span class="muted">${c.tournament.matches.length} REGISTRADOS</span></div>${c.tournament.matches.map(m=>`<article class="panel match"><div class="section-line"><span class="eyebrow">${e(m.round)}</span><button class="text-button" data-match="${e(m.id)}">Editar ↗</button></div><div class="versus"><strong>${e(name(m.a))}</strong><span>×</span><strong>${e(name(m.b))}</strong></div>${badge(m.winner?(m.winner==='empate'?'Empate':`Vitória: ${name(m.winner)}`):'Aguardando resultado')}<p>${e(m.notes)}</p></article>`).join('')||empty('As chaves ainda estão abertas','Nenhuma luta foi inventada. Adicione confrontos conforme o Conselho decidir.')}</section></div>`;
}
